server.registerTool("sale_update", {
  title: "Change a bill of sale before signing",
  description: "Change anything on a bill of sale that is not finalized yet: price, buyer, seller, item details, identifiers, the as-is clause, warranty or notes. Pass an empty string to clear an optional field. A finalized document cannot be edited.",
  inputSchema: {
    sale: saleArg,
    buyer_name: str("name", MAX_NAME).optional().describe("Who is buying"),
    buyer_address: str("address", MAX_TEXT).optional(),
    buyer_email: str("email", MAX_NAME).optional(),
    buyer_phone: str("phone", MAX_NAME).optional(),
    seller_name: str("name", MAX_NAME).optional().describe("Who is selling"),
    seller_address: str("address", MAX_TEXT).optional(),
    seller_email: str("email", MAX_NAME).optional(),
    seller_phone: str("phone", MAX_NAME).optional(),
    item_description: str("item_description", MAX_TEXT).optional(),
    item_category: str("item_category", MAX_NAME).optional(),
    vin: str("vin", 40).optional(),
    serial: str("serial", MAX_NAME).optional(),
    imei: str("imei", 20).optional(),
    identifier_other: str("identifier_other", MAX_NAME).optional(),
    quantity: z.number().int().min(1).max(100000).optional(),
    condition: str("condition", MAX_NAME).optional(),
    price_minor: z.number().int().min(0).max(MAX_MINOR).optional().describe("The sale price in whole minor units (integer cents)"),
    currency: z.string().regex(/^[A-Za-z]{3}$/, "currency must be a 3-letter ISO code such as USD").optional(),
    date: str("date", 10).optional().describe("The date of the sale, YYYY-MM-DD"),
    as_is: z.boolean().optional(),
    warranty: str("warranty", MAX_TEXT).optional(),
    notes: str("notes", MAX_TEXT).optional(),
  },
}, async (a) => {
  try {
    if (a.date !== undefined) checkDate(a.date, "date");
    const out = await locked(() => {
      const list = getSales();
      const s = findSale(list, a.sale);
      if (s.status === "final") {
        throw new Error(
          `${s.id} is finalized and cannot be edited. A finalized bill of sale is the signing copy, and editing it here would not change the copy the buyer may already hold. ` +
          `If the facts changed, sale_delete it with confirm_finalized true and record the sale again. Nothing was written.`,
        );
      }
      const setOpt = (provided: string | undefined, set: (v?: string) => void) => {
        if (provided === undefined) return;
        const t = provided.trim();
        set(t === "" ? undefined : t);
      };
      let touched = 0;
      const touch = () => { touched += 1; };
      setOpt(a.buyer_name, (v) => { if (v === undefined) throw new Error("buyer_name cannot be cleared: a bill of sale needs a buyer. Nothing was written."); s.buyer.name = v; touch(); });
      setOpt(a.buyer_address, (v) => { s.buyer.address = v; touch(); });
      setOpt(a.buyer_email, (v) => { s.buyer.email = v; touch(); });
      setOpt(a.buyer_phone, (v) => { s.buyer.phone = v; touch(); });
      setOpt(a.seller_name, (v) => { if (v === undefined) throw new Error("seller_name cannot be cleared: a bill of sale needs a seller. Nothing was written."); s.seller.name = v; touch(); });
      setOpt(a.seller_address, (v) => { s.seller.address = v; touch(); });
      setOpt(a.seller_email, (v) => { s.seller.email = v; touch(); });
      setOpt(a.seller_phone, (v) => { s.seller.phone = v; touch(); });
      setOpt(a.item_description, (v) => { if (v === undefined) throw new Error("item_description cannot be cleared: the document must say what was sold. Nothing was written."); s.item.description = v; touch(); });
      setOpt(a.item_category, (v) => { s.item.category = v; touch(); });
      setOpt(a.condition, (v) => { s.item.condition = v; touch(); });
      if (a.quantity !== undefined) { s.item.quantity = a.quantity; touch(); }
      if (a.price_minor !== undefined) { s.price_minor = a.price_minor; touch(); }
      if (a.currency !== undefined) { s.currency = a.currency.toUpperCase(); touch(); }
      if (a.date !== undefined) { s.date = a.date; touch(); }
      if (a.as_is !== undefined) { s.as_is = a.as_is; touch(); }
      setOpt(a.warranty, (v) => { s.warranty = v; touch(); });
      setOpt(a.notes, (v) => { s.notes = v; touch(); });
      const anyIdentifier = a.vin !== undefined || a.serial !== undefined || a.imei !== undefined || a.identifier_other !== undefined;
      if (anyIdentifier) {
        const ids = s.item.identifiers ?? {};
        setOpt(a.vin, (v) => { ids.vin = v; touch(); });
        setOpt(a.serial, (v) => { ids.serial = v; touch(); });
        setOpt(a.imei, (v) => { ids.imei = v; touch(); });
        setOpt(a.identifier_other, (v) => { ids.other = v; touch(); });
        s.item.identifiers = (ids.vin || ids.serial || ids.imei || ids.other) ? ids : undefined;
      }
      if (touched === 0) {
        throw new Error("nothing to change: no field was passed. Updatable fields are buyer_*, seller_*, item_description, item_category, vin, serial, imei, identifier_other, quantity, condition, price_minor, currency, date, as_is, warranty, notes. Nothing was written.");
      }
      s.updated = new Date().toISOString();
      setSales(list);
      return { s };
    });
    const notes: string[] = [];
    for (const n of identifierNotes(out.s.item.identifiers ?? {})) notes.push(n.note);
    return json({ updated: saleJson(out.s), notes });
  } catch (e) { return fail((e as Error).message); }
});

server.registerTool("sale_finalize", {
  title: "Finalize the bill of sale for signing",
  description: "Finalize a bill of sale so it is ready to sign: the document is frozen from this call on, sale_update refuses it, and every later render is the signing copy without the DRAFT watermark. Free tier: 5 finalized documents.",
  inputSchema: { sale: saleArg },
}, async (a) => {
  try {
    const out = await locked(() => {
      const list = getSales();
      const s = findSale(list, a.sale);
      if (s.status === "final") {
        throw new Error(`${s.id} was already finalized on ${s.finalized_on?.slice(0, 10)}. It is the signing copy; sale_render prints it. Nothing was written.`);
      }
      const finals = list.filter((x) => x.status === "final").length;
      if (!gate.isPro() && finals >= FREE_FINALIZED) {
        throw new Error(
          `the free tier finalizes ${FREE_FINALIZED} documents and ${finals} are already finalized (${list.filter((x) => x.status === "final").map((x) => x.id).join(", ")}). ` +
          `Rendering a draft stays free, so the document can still be proofed and copied out by hand. Nothing was written. ` + gate.upgradeText("unlimited finalized documents", "sale_finalize"),
        );
      }
      s.status = "final";
      s.finalized_on = new Date().toISOString();
      s.updated = s.finalized_on;
      setSales(list);
      return { s };
    });
    return json({
      finalized: saleJson(out.s),
      note: `${out.s.id} is frozen. sale_render {sale: "${out.s.id}"} prints the signing copy with signature lines for seller and buyer.`,
    });
  } catch (e) { return fail((e as Error).message); }
});

server.registerTool("sale_list", {
  title: "List bills of sale",
  description: "List every bill of sale, drafts and finalized, newest first: id, status, date, item, buyer, seller and price. Filter to drafts or finalized documents with status.",
  inputSchema: {
    status: z.enum(["all", "draft", "final"]).optional().describe("Which documents to list: all (default), draft, or final"),
    limit: z.number().int().min(1).max(MAX_ROWS).optional().describe(`Maximum rows, default ${MAX_ROWS}`),
  },
}, async (a) => {
  try {
    const all = getSales();
    const filtered = (a.status && a.status !== "all" ? all.filter((s) => s.status === a.status) : all)
      .sort((x, y) => (x.created === y.created ? y.id.localeCompare(x.id) : x.created < y.created ? 1 : -1));
    const limit = a.limit ?? MAX_ROWS;
    return json({
      count: Math.min(filtered.length, limit),
      total: filtered.length,
      truncated: filtered.length > limit,
      drafts: all.filter((s) => s.status === "draft").length,
      finalized: all.filter((s) => s.status === "final").length,
      sales: filtered.slice(0, limit).map(rowJson),
    });
  } catch (e) { return fail((e as Error).message); }
});

