      const list = getSales();
      const s = findSale(list, a.sale);
      if (s.status === "final" && a.confirm_finalized !== true) {
        throw new Error(
          `${s.id} is finalized. Deleting it removes the local copy of a document the buyer may already hold on paper; it does not undo the sale. ` +
          `Pass confirm_finalized true if that is really what you want. Nothing was written.`,
        );
      }
      setSales(list.filter((x) => x.id !== s.id));
